postToolUse.bash:
i=$(cat); JP=""; JN=""; for c in python python3; do if command -v "$c" >/dev/null 2>&1; then JP=$c; break; fi; done; if [ -z "$JP" ] && command -v node >/dev/null 2>&1; then JN=node; fi; jr(){ if [ -n "$JP" ]; then "$JP" -c "$1" 2>/dev/null | tr -d "\r"; elif [ -n "$JN" ]; then "$JN" -e "$2" 2>/dev/null | tr -d "\r"; else return 127; fi; }; emit(){ jr "import sys,json;sys.stdout.write(json.dumps({\"additionalContext\":sys.stdin.buffer.read().decode(\"utf-8\",\"replace\")[:8000]}))" "process.stdout.write(JSON.stringify({additionalContext:require(\"fs\").readFileSync(0,\"utf8\").slice(0,8000)}));"; }; if [ -z "$JP" ] && [ -z "$JN" ]; then printf '%s' 'SDLC gate hook did NOT run: no JSON parser (python or node) on the PATH of the shell this CLI runs hooks in. The gate did not check this file.' | sed "s/.*/{\"additionalContext\":\"&\"}/"; exit 0; fi; o=$(printf '%s' "$i" | jr '
import sys,json,re
d=json.loads(sys.stdin.buffer.read().decode("utf-8","replace"))
o=[d.get("cwd") or ""]
a=d.get("toolArgs") or d.get("tool_input") or {}
if isinstance(a,str) and a.lstrip()[:1] not in "{[":
    h=re.findall(r"^\*\*\* (Add|Update|Delete) File: (.+)$",a,re.M)
    o.append("ok" if h else "nopath")
    o+=[v.strip() for k,v in h if k!="Delete"]
else:
    a=json.loads(a) if isinstance(a,str) else a
    p=a.get("path") or a.get("file_path") or a.get("filePath") or a.get("filename") or a.get("file") or ""
    o.append("ok" if p else "nopath")
    if p: o.append(p)
sys.stdout.write("\n".join(o)+"\n")
' '
const d=JSON.parse(require("fs").readFileSync(0,"utf8"));
const o=[d.cwd||""];
let a=d.toolArgs||d.tool_input||{};
if(typeof a==="string" && !"{[".includes(a.trimStart()[0]||"")){
  const h=[...a.matchAll(/^\*\*\* (Add|Update|Delete) File: (.+)$/gm)];
  o.push(h.length?"ok":"nopath");
  for(const m of h) if(m[1]!=="Delete") o.push(m[2].trim());
}else{
  if(typeof a==="string") a=JSON.parse(a);
  const p=a.path||a.file_path||a.filePath||a.filename||a.file||"";
  o.push(p?"ok":"nopath");
  if(p) o.push(p);
}
process.stdout.write(o.join("\n")+"\n");
'); w=$(printf '%s' "$o" | sed -n 1p); st=$(printf '%s' "$o" | sed -n 2p); if [ -n "$w" ] && [ -d "$w" ]; then cd "$w" || exit 0; fi; if [ "$st" != "ok" ]; then printf '%s' 'SDLC gate hook did NOT run on this edit: no file path found in the hook payload. The gate did not check this file - fix the hook before trusting it (discovery procedure: COPILOT.md in the kit folder or the kit home repository).' | emit; exit 0; fi; out=$(printf '%s\n' "$o" | tail -n +3 | while IFS= read -r f; do [ -n "$f" ] || continue; case "$f" in {{SOURCE_GLOB}}) ;; *) continue ;; esac; if [ ! -f "$f" ]; then printf 'SDLC gate hook did NOT run: the edited file was not found from the hook working directory: %s\n' "$f"; continue; fi; l=$({{HOOK_LINT_CMD}} 2>&1); lrc=$?; t=""; trc=0; {{HOOK_TYPECHECK_BLOCK}} if [ $lrc -ne 0 ] || [ $trc -ne 0 ]; then printf 'SDLC gate hook: lint/typecheck failed on the file just edited. Fix it before continuing: %s\n%s\n%s\n' "$f" "$l" "$t"; fi; done); if [ -n "$out" ]; then printf '%s' "$out" | emit; fi; exit 0
